DROP TABLE IF EXISTS `activite`;
CREATE TABLE `activite` (
  `id_activite` int NOT NULL AUTO_INCREMENT,
  `id_destination` int NOT NULL,
  `id_hote` int NOT NULL,
  `nom` varchar(150) NOT NULL,
  `description` text,
  `categorie` enum('aventure','culture','nature','gastronomie','bien_etre') NOT NULL,
  `prix_personne` decimal(10,2) NOT NULL,
  `duree_h` decimal(4,1) DEFAULT NULL,
  `niveau` enum('facile','moyen','difficile') DEFAULT 'facile',
  `image_url` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id_activite`),
  KEY `fk_activite_destination` (`id_destination`),
  KEY `fk_activite_hote` (`id_hote`),
  CONSTRAINT `fk_activite_destination` FOREIGN KEY (`id_destination`) REFERENCES `destination` (`id_destination`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_activite_hote` FOREIGN KEY (`id_hote`) REFERENCES `utilisateur` (`id_utilisateur`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_activite_prix` CHECK ((`prix_personne` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
LOCK TABLES `activite` WRITE;
INSERT INTO `activite` VALUES (1,1,2,'Cours de cuisine balinaise','Apprenez à préparer nasi goreng, satay lilit et jamu. Visite du marché matinal incluse pour choisir les épices avec une cuisinière locale.','gastronomie',45.00,3.0,'facile','https://images.unsplash.com/photo-1606787366850-de6330128bfc?w=800'),(2,1,2,'Randonnée volcan Batur au lever','Ascension nocturne du Gunung Batur (1717 m), départ 2h du matin, lever de soleil depuis le sommet. Petit-déjeuner cuit à la vapeur volcanique inclus.','aventure',65.00,8.0,'difficile','https://images.unsplash.com/photo-1506197603052-3cc9c3a201bd?w=800'),(3,2,3,'Soirée Fado & Gastronomie','Dîner dans un restaurant fado historique de l\'Alfama, menu dégustation 5 plats avec explications culturelles par une fadiste locale. Vinho verde inclus.','culture',38.00,3.5,'facile','https://images.unsplash.com/photo-1555041469-a586c61ea9bc?w=800'),(4,2,3,'Surf à Cascais','Session surf tous niveaux à Cascais avec instructeur francophone. Combinaison, planche et transfert depuis Lisbonne inclus.','aventure',55.00,3.0,'moyen','https://images.unsplash.com/photo-1517699418036-fb5d179fef0c?w=800'),(5,3,3,'Atelier teinture textile zapotèque','Techniques de teinture au cochenille et à l\'indigo auprès d\'un artisan zapotèque. Repartez avec le châle que vous aurez teint vous-même.','culture',42.00,4.0,'facile','https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800'),(6,3,3,'Visite ruines de Monte Albán','Visite guidée du site archéologique zapotèque classé UNESCO (500 av. J.-C.) avec un passionné local. Transfert et déjeuner traditionnel inclus.','culture',28.00,5.0,'facile','https://images.unsplash.com/photo-1518638150340-f706e86654de?w=800'),(7,4,4,'Cérémonie du thé Urasenke','Cérémonie authentique dans un pavillon du XVIe siècle, officiant en kimono. Introduction au wabi-sabi et initiation à la calligraphie incluse.','culture',55.00,2.0,'facile','https://images.unsplash.com/photo-1545579133-99bb5ad189be?w=800'),(8,4,4,'Méditation zen à Arashiyama','Session zazen guidée par un moine du temple Tenryu-ji au bord de la forêt de bambous, suivie d\'une marche contemplative matinale. Départ 6h.','bien_etre',48.00,2.5,'facile','https://images.unsplash.com/photo-1528360983277-13d401cdc186?w=800'),(9,5,5,'Cours de cuisine marocaine','Tajine d\'agneau, pastilla et cornes de gazelle chez Fatima dans sa maison familiale. Visite du souk aux épices et déjeuner partagé inclus.','gastronomie',40.00,4.0,'facile','https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800'),(10,5,5,'Hammam traditionnel & gommage','Hammam centenaire de la médina : gommage au savon beldi, enveloppement au rhassoul, massage à l\'huile d\'argan. Serviettes et savon fournis.','bien_etre',32.00,2.0,'facile','https://images.unsplash.com/photo-1540555700478-4be289fbecef?w=800'),(11,6,6,'Tour street art Comuna 13','Visite guidée du quartier Comuna 13 racontée par des habitants. Escalators urbains, fresques, musique hip-hop local et témoignages des résidents.','culture',22.00,3.0,'facile','https://images.unsplash.com/photo-1570168007204-dfb528c6958f?w=800'),(12,6,6,'Randonnée café en Antioquia','Excursion dans une finca caféière d\'altitude : cueillette, transformation et dégustation. Déjeuner campagnard et transfert depuis Medellín inclus.','nature',38.00,6.0,'moyen','https://images.unsplash.com/photo-1447933601403-0c6688de566e?w=800'),(13,7,2,'Visite guidee du Louvre','Parcours des chefs-d\'oeuvre du Louvre avec un guide expert, sans file d\'attente.','culture',45.00,3.0,'facile','https://images.unsplash.com/photo-1499856871958-5b9627545d1a?w=800'),(14,7,2,'Croisiere sur la Seine','Diner croisiere romantique au coucher du soleil, monuments illumines en fond.','culture',85.00,2.0,'facile','https://images.unsplash.com/photo-1502602898657-3e91760cbb34?w=800'),(15,8,2,'Tour Vatican et Chapelle Sixtine','Visite guidee en petit groupe du Vatican, Musees et Chapelle Sixtine.','culture',55.00,4.0,'facile','https://images.unsplash.com/photo-1531572753322-ad063cecc140?w=800'),(16,8,2,'Cours de cuisine romaine','Apprenez a preparer pates fraiches et tiramisu avec un chef romain chez lui.','gastronomie',40.00,3.0,'facile','https://images.unsplash.com/photo-1466637574441-749b8f19452f?w=800'),(17,9,2,'Visite de la Sagrada Familia','Decouvrez l\'oeuvre de Gaudi avec acces aux tours et guide expert sur place.','culture',35.00,2.0,'facile','https://images.unsplash.com/photo-1539037116277-4db20889f2d4?w=800'),(18,9,2,'Cours de flamenco','Initiation au flamenco par une danseuse professionnelle dans un tablao authentique.','culture',30.00,1.5,'facile','https://images.unsplash.com/photo-1518611012118-696072aa579a?w=800'),(19,10,2,'Tour des temples a velo','Explorez les temples bouddhistes de Bangkok a velo avec un guide local passionne.','aventure',25.00,4.0,'facile','https://images.unsplash.com/photo-1508009603885-50cf7c579365?w=800'),(20,10,2,'Cuisine thaie au marche','Visite d\'un marche local puis cours de cuisine avec 5 plats typiques a preparer.','gastronomie',35.00,5.0,'facile','https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=800'),(21,11,2,'Atelier lanterne a Hoi An','Fabriquez votre propre lanterne en soie avec une artisane locale, tradition seculaire.','culture',20.00,2.0,'facile','https://images.unsplash.com/photo-1528360983277-13d401cdc186?w=800'),(22,11,2,'Balade en barque Thu Bon','Promenade en barque au coucher du soleil sur la riviere Thu Bon, ilots de cocotiers.','nature',30.00,2.0,'facile','https://images.unsplash.com/photo-1553697388-94e804e2f0f6?w=800'),(23,12,2,'Randonnee Table Mountain','Ascension guidee de la Montagne de la Table, vue panoramique sur Le Cap.','aventure',40.00,5.0,'moyen','https://images.unsplash.com/photo-1580060839134-75a5edca2e99?w=800'),(24,12,2,'Tour des townships','Visite immersive des townships de Cape Town, histoire de l\'apartheid.','culture',35.00,4.0,'facile','https://images.unsplash.com/photo-1611348524140-53c9a25263d6?w=800'),(25,13,2,'Cours de tango','Lecon de tango avec un couple de danseurs professionnels dans une milonga San Telmo.','culture',30.00,2.0,'facile','https://images.unsplash.com/photo-1518611012118-696072aa579a?w=800'),(26,13,2,'Asado et visite d\'estancia','Journee dans un ranch argentin, balade a cheval et asado traditionnel sous les etoiles.','gastronomie',75.00,8.0,'facile','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=800'),(27,14,2,'Cours de salsa cubaine','Initiation a la salsa cubaine suivie d\'une degustation de rhums avec un expert.','culture',35.00,3.0,'facile','https://images.unsplash.com/photo-1559517485-17c3bd224bd5?w=800'),(28,14,2,'Promenade en Chevrolet 1956','Balade dans La Havane a bord d\'une Chevrolet 1956 decapotable avec chauffeur guide.','culture',50.00,2.0,'facile','https://images.unsplash.com/photo-1500759285222-a95626b934cb?w=800'),(29,15,2,'Snorkeling Grande Barriere','Excursion en catamaran, snorkeling encadre par des biologistes marins professionnels.','aventure',110.00,8.0,'moyen','https://images.unsplash.com/photo-1433086966358-54859d0ed716?w=800'),(30,15,2,'Visite de l\'Opera de Sydney','Decouvrez les coulisses de l\'Opera de Sydney avec un guide passionne d\'architecture.','culture',45.00,1.5,'facile','https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?w=800'),(31,16,2,'Plongee au recif de Mnemba','Plongee guidee autour de l\'ile de Mnemba, coraux et tortues marines.','aventure',80.00,4.0,'moyen','https://images.unsplash.com/photo-1586500036706-41963de24d8b?w=800'),(32,16,2,'Epices et cuisine zanzibarie','Tour d\'une plantation d\'epices puis cours de cuisine swahilie locale.','gastronomie',45.00,5.0,'facile','https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=800'),(33,17,2,'Croisiere canaux et moulins','Croisiere en peniche sur les canaux d\'Amsterdam et moulins de Zaanse Schans.','nature',55.00,5.0,'facile','https://images.unsplash.com/photo-1534351590666-13e3e96b5017?w=800'),(34,17,2,'Rijksmuseum et Van Gogh','Visite guidee couplee du Rijksmuseum et du Musee Van Gogh avec acces prioritaire.','culture',65.00,4.0,'facile','https://images.unsplash.com/photo-1499856871958-5b9627545d1a?w=800'),(35,18,2,'Tour en helicoptere Manhattan','Survol en helicoptere des gratte-ciels de Manhattan, vue sur la Statue de la Liberte.','aventure',200.00,1.0,'facile','https://images.unsplash.com/photo-1496442226666-8d4d0e62e6e9?w=800'),(36,18,2,'Food tour Brooklyn','Tour culinaire dans Brooklyn : bagels, pizza, cheesecake et bieres artisanales.','gastronomie',55.00,4.0,'facile','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=800'),(37,19,2,'Meditation au Doi Suthep','Journee de meditation et yoga au temple Doi Suthep avec un moine bouddhiste.','bien_etre',30.00,6.0,'facile','https://images.unsplash.com/photo-1528181304800-259b08848526?w=800'),(38,19,2,'Cuisine du Nord Thailande','Marche matinal puis atelier de cuisine de la region Lanna avec une cheffe locale.','gastronomie',40.00,5.0,'facile','https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=800'),(39,20,2,'Desert de nuit a Dubai','Safari 4x4 dans les dunes au coucher du soleil, diner sous les etoiles et danse.','aventure',95.00,5.0,'facile','https://images.unsplash.com/photo-1512453979798-5ea266f8880c?w=800'),(40,20,2,'Burj Khalifa et Souk de l\'Or','Montee au sommet du Burj Khalifa puis visite du Souk de l\'Or et des epices.','culture',70.00,3.0,'facile','https://images.unsplash.com/photo-1499856871958-5b9627545d1a?w=800'),(41,21,2,'Visite Sainte-Sophie et Grand Bazar','Decouvrez les joyaux ottomans d\'Istanbul avec un guide passionne, marche aux epices inclus.','culture',40.00,4.0,'facile','https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?w=800'),(42,21,2,'Croisiere sur le Bosphore','Croisiere au coucher du soleil entre Europe et Asie, palais ottomans et forteresses en vue.','nature',35.00,2.5,'facile','https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?w=800');
UNLOCK TABLES;
DROP TABLE IF EXISTS `creneau`;
CREATE TABLE `creneau` (
  `id_creneau` int NOT NULL AUTO_INCREMENT,
  `id_activite` int NOT NULL,
  `date_heure` datetime NOT NULL,
  `places_totales` int NOT NULL,
  `places_restantes` int NOT NULL,
  PRIMARY KEY (`id_creneau`),
  KEY `fk_creneau_activite` (`id_activite`),
  CONSTRAINT `fk_creneau_activite` FOREIGN KEY (`id_activite`) REFERENCES `activite` (`id_activite`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_creneau_places` CHECK (((`places_restantes` >= 0) and (`places_restantes` <= `places_totales`)))
) ENGINE=InnoDB AUTO_INCREMENT=127 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
LOCK TABLES `creneau` WRITE;
