DROP TABLE IF EXISTS `destination`;
CREATE TABLE `destination` (
  `id_destination` int NOT NULL AUTO_INCREMENT,
  `id_admin` int DEFAULT NULL,
  `nom` varchar(150) NOT NULL,
  `pays` varchar(100) NOT NULL,
  `region` varchar(100) DEFAULT NULL,
  `latitude` decimal(9,6) DEFAULT NULL,
  `longitude` decimal(9,6) DEFAULT NULL,
  `description` text,
  `image_url` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id_destination`),
  KEY `fk_destination_admin` (`id_admin`),
  CONSTRAINT `fk_destination_admin` FOREIGN KEY (`id_admin`) REFERENCES `utilisateur` (`id_utilisateur`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
LOCK TABLES `destination` WRITE;
INSERT INTO `destination` VALUES (1,1,'Ubud','Indonésie','Bali',-8.506400,115.261900,'Cœur culturel de Bali, entouré de rizières en terrasses et de temples anciens. Idéal pour une immersion dans les arts, la spiritualité et la gastronomie balinaise.','https://images.unsplash.com/photo-1537996194471-e657df975ab4?w=800'),(2,1,'Lisbonne','Portugal','Région de Lisbonne',38.722300,-9.139300,'Capitale en pente douce sur le Tage, mosaïque de quartiers historiques, de fado et de gastronomie. Une ville qui invite à ralentir et à se perdre.','https://images.unsplash.com/photo-1548707309-dcebeab9ea9b?w=800'),(3,1,'Oaxaca','Mexique','Oaxaca',17.073200,-96.726600,'Ville coloniale au cœur du Mexique indigène, réputée pour sa gastronomie, ses textiles et ses ruines zapotèques.','https://images.unsplash.com/photo-1518638150340-f706e86654de?w=800'),(4,1,'Kyoto','Japon','Kansai',35.011600,135.768100,'Ancienne capitale impériale, gardienne de la tradition entre temples zen, jardins de mousse et maisons de thé.','https://images.unsplash.com/photo-1528360983277-13d401cdc186?w=800'),(5,1,'Marrakech','Maroc','Région Marrakech',31.629500,-7.981100,'La ville ocre, labyrinthe de souks, de riads et de jardins secrets. Une immersion totale dans la culture berbère à deux heures de Paris.','https://images.unsplash.com/photo-1539020140153-e479b8c22e70?w=800'),(6,1,'Medellín','Colombie','Antioquia',6.244200,-75.581200,'La ville de l\'éternel printemps, métamorphosée en laboratoire d\'innovation sociale. Street art, café de montagne et chaleur humaine.','https://images.unsplash.com/photo-1570168007204-dfb528c6958f?w=800'),(7,NULL,'Paris','France',NULL,NULL,NULL,'La Ville Lumiere, capitale mondiale de l\'art, de la mode et de la gastronomie.','https://images.unsplash.com/photo-1502602898657-3e91760cbb34?w=800'),(8,NULL,'Rome','Italie',NULL,NULL,NULL,'La Ville Eternelle, berceau de la civilisation occidentale et du patrimoine antique.','https://images.unsplash.com/photo-1552832230-c0197dd311b5?w=800'),(9,NULL,'Barcelone','Espagne',NULL,NULL,NULL,'Capitale catalane vibrante, entre architecture moderniste de Gaudi et plages mediterraneennes.','https://images.unsplash.com/photo-1539037116277-4db20889f2d4?w=800'),(10,NULL,'Bangkok','Thaïlande',NULL,NULL,NULL,'Metropole trepidante aux temples dores, street food legendaire et vie nocturne electrisante.','https://images.unsplash.com/photo-1508009603885-50cf7c579365?w=800'),(11,NULL,'Hoi An','Vietnam',NULL,NULL,NULL,'Ancienne cite marchande aux lanternes colorees, ruelles pavees et cuisine raffinee.','https://images.unsplash.com/photo-1528360983277-13d401cdc186?w=800'),(12,NULL,'Le Cap','Afrique du Sud',NULL,NULL,NULL,'Ville cosmopolite au pied de la Montagne de la Table, entre oceans et vignobles.','https://images.unsplash.com/photo-1580060839134-75a5edca2e99?w=800'),(13,NULL,'Buenos Aires','Argentine',NULL,NULL,NULL,'Paris de l\'Amerique du Sud, capitale du tango, des biftecks et de l\'architecture europeenne.','https://images.unsplash.com/photo-1589909202802-8f4aadce1849?w=800'),(14,NULL,'La Havane','Cuba',NULL,NULL,NULL,'Capitale hors du temps aux voitures americaines d\'epoque, musique omnipresente et architecture coloniale.','https://images.unsplash.com/photo-1500759285222-a95626b934cb?w=800'),(15,NULL,'Sydney','Australie',NULL,NULL,NULL,'Metropole dynamique autour d\'un port iconique, plages de sable blanc et culture de plein air.','https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?w=800'),(16,NULL,'Zanzibar','Tanzanie',NULL,NULL,NULL,'Ile aux epices baignee de l\'ocean Indien, avec ses plages de reve et sa medina historique.','https://images.unsplash.com/photo-1586500036706-41963de24d8b?w=800'),(17,NULL,'Amsterdam','Pays-Bas',NULL,NULL,NULL,'Cite des canaux, des velos et des musees de classe mondiale dans un cadre unique.','https://images.unsplash.com/photo-1534351590666-13e3e96b5017?w=800'),(18,NULL,'New York','États-Unis',NULL,NULL,NULL,'La Ville qui ne dort jamais : gratte-ciels, diversite culturelle et energie incomparable.','https://images.unsplash.com/photo-1496442226666-8d4d0e62e6e9?w=800'),(19,NULL,'Chiang Mai','Thaïlande',NULL,NULL,NULL,'Ancienne capitale du Nord, entouree de temples, jungles luxuriantes et traditions Lanna.','https://images.unsplash.com/photo-1528181304800-259b08848526?w=800'),(20,NULL,'Dubaï','Émirats arabes unis',NULL,NULL,NULL,'Cite futuriste du desert, entre gratte-ciels vertigineux, souks authentiques et plages de luxe.','https://images.unsplash.com/photo-1512453979798-5ea266f8880c?w=800'),(21,NULL,'Istanbul','Turquie',NULL,NULL,NULL,'Cite a cheval sur deux continents, entre mosquees ottomanes, bazars envoûtants et Bosphore scintillant.','https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?w=800');
UNLOCK TABLES;
DROP TABLE IF EXISTS `disponibilite`;
CREATE TABLE `disponibilite` (
  `id_dispo` int NOT NULL AUTO_INCREMENT,
  `id_hebergement` int NOT NULL,
  `date_debut` date NOT NULL,
  `date_fin` date NOT NULL,
  `statut` enum('ouverte','reservee','bloquee') NOT NULL DEFAULT 'ouverte',
  PRIMARY KEY (`id_dispo`),
  KEY `idx_dispo_recherche` (`id_hebergement`,`statut`,`date_debut`,`date_fin`),
  CONSTRAINT `fk_dispo_hebergement` FOREIGN KEY (`id_hebergement`) REFERENCES `hebergement` (`id_hebergement`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_dispo_dates` CHECK ((`date_fin` > `date_debut`))
) ENGINE=InnoDB AUTO_INCREMENT=86 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
LOCK TABLES `disponibilite` WRITE;
