UNLOCK TABLES;
DROP TABLE IF EXISTS `hebergement`;
CREATE TABLE `hebergement` (
  `id_hebergement` int NOT NULL AUTO_INCREMENT,
  `id_destination` int NOT NULL,
  `id_hote` int NOT NULL,
  `nom` varchar(150) NOT NULL,
  `type` enum('appartement','maison','villa','chambre','autre') NOT NULL,
  `description` text,
  `capacite` int NOT NULL,
  `prix_semaine` decimal(10,2) NOT NULL,
  `duree_min_nuits` int NOT NULL DEFAULT '7',
  `image_url` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id_hebergement`),
  KEY `fk_hebergement_destination` (`id_destination`),
  KEY `fk_hebergement_hote` (`id_hote`),
  CONSTRAINT `fk_hebergement_destination` FOREIGN KEY (`id_destination`) REFERENCES `destination` (`id_destination`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_hebergement_hote` FOREIGN KEY (`id_hote`) REFERENCES `utilisateur` (`id_utilisateur`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_hebergement_capacite` CHECK ((`capacite` > 0)),
  CONSTRAINT `chk_hebergement_duree` CHECK ((`duree_min_nuits` >= 1)),
  CONSTRAINT `chk_hebergement_prix` CHECK ((`prix_semaine` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
LOCK TABLES `hebergement` WRITE;
INSERT INTO `hebergement` VALUES (1,1,2,'Villa Ubud Serenity','villa','Villa traditionnelle balinaise avec piscine privée, vue sur les rizières et cour intérieure. Petit-déjeuner balinais quotidien inclus.',4,850.00,7,'https://images.unsplash.com/photo-1571003123894-1f0594d2b5d9?w=800'),(2,1,2,'Appartement Seminyak Vue Mer','appartement','Appartement contemporain à 5 min de la plage de Seminyak, terrasse privée, cuisine équipée, vélos inclus.',2,490.00,7,'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?w=800'),(3,2,3,'Maison Alfama dos Azulejos','maison','Maison de ville entière dans l\'Alfama historique, carrelages azulejos d\'époque, terrasse avec vue sur le Tage.',6,980.00,7,'https://images.unsplash.com/photo-1564501049412-61c2a3083791?w=800'),(4,2,3,'Chambre Mouraria Vintage','chambre','Chambre privée dans une maison d\'hôtes au cœur de Mouraria, berceau du fado. Petit-déjeuner portugais compris.',1,210.00,7,'https://images.unsplash.com/photo-1631049307264-da0ec9d70304?w=800'),(5,3,3,'Casa Colonial Oaxaca Centro','maison','Maison coloniale en centre historique, patio fleuri, bibliothèque et cuisine mexicaine équipée. À deux pas du marché Benito Juárez.',4,560.00,7,'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=800'),(6,3,3,'Villa Monte Albán','villa','Grande villa avec piscine et vue sur la vallée d\'Oaxaca. Cuisine professionnelle, jardin d\'herbes aromatiques. Idéale pour groupe ou retraite.',8,1250.00,7,'https://images.unsplash.com/photo-1499793983690-e29da59ef1c2?w=800'),(7,4,4,'Machiya Higashiyama','maison','Maison en bois du XIXe s. entièrement restaurée près des temples de Higashiyama. Bain japonais ofuro, jardin intérieur, tatamis.',3,1100.00,7,'https://images.unsplash.com/photo-1580060839134-75a5edca2e99?w=800'),(8,4,4,'Appartement Arashiyama','appartement','Appartement moderne avec vue sur la forêt de bambous. Cuisine style japonais, vélos inclus pour rejoindre Togetsukyo.',2,650.00,7,'https://images.unsplash.com/photo-1576675784432-a3a43cefa1a0?w=800'),(9,5,5,'Riad Médina Enchantée','villa','Riad authentique en médina, 3 suites décorées à la main, patio fontaine, terrasse sur les toits. Petit-déjeuner marocain et hammam privatisable.',6,820.00,7,'https://images.unsplash.com/photo-1539037116277-4db20889f2d4?w=800'),(10,5,5,'Chambre Palmeraie','chambre','Chambre double dans un riad de la Palmeraie entouré de palmiers et d\'une piscine. Idéale pour un couple cherchant le calme.',2,290.00,7,'https://images.unsplash.com/photo-1577791465485-b8d0c7b96908?w=800'),(11,6,6,'Appartement El Poblado','appartement','Appartement design dans le quartier branché d\'El Poblado, terrasse avec vue sur la ville, accès coworking inclus. Parfait nomade digital.',3,380.00,7,'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800'),(12,6,6,'Maison Laureles','maison','Maison familiale dans le quartier résidentiel de Laureles, jardin tropical, hamac, cuisine équipée. Ambiance locale garantie, métro à 200 m.',5,640.00,7,'https://images.unsplash.com/photo-1564013799919-ab600027ffc6?w=800'),(13,7,2,'Appartement Marais','appartement','Charmant appartement haussmannien au coeur du Marais, pres du Centre Pompidou.',2,840.00,7,'https://images.unsplash.com/photo-1566195992011-5f6b21e539aa?w=800'),(14,7,2,'Studio Tour Eiffel','autre','Studio cosy avec vue sur la Tour Eiffel, bien equipe et idealement situe.',2,665.00,7,'https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?w=800'),(15,8,2,'Appartement Trastevere','appartement','Appartement pittoresque dans le quartier boheme de Trastevere, ambiance authentique.',3,770.00,7,'https://images.unsplash.com/photo-1555854877-bab0e564b8d5?w=800'),(16,8,2,'Suite Colisee','autre','Suite elegante a cinq minutes du Colisee, terrasse privee avec vue sur les ruines.',2,1260.00,7,'https://images.unsplash.com/photo-1611892440504-42a792e24d32?w=800'),(17,9,2,'Appartement Eixample','appartement','Appartement lumineux dans le quartier Art Nouveau, pres de la Sagrada Familia.',4,735.00,7,'https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?w=800'),(18,9,2,'Studio Barceloneta','autre','Studio moderne a 50 m de la plage de la Barceloneta, vue mer depuis le balcon.',2,630.00,7,'https://images.unsplash.com/photo-1522771739844-6a9f6d5f14af?w=800'),(19,10,2,'Appartement Sukhumvit','appartement','Appartement moderne en plein coeur de Bangkok, acces direct au BTS Skytrain.',3,525.00,7,'https://images.unsplash.com/photo-1598928506311-c55ded91a20c?w=800'),(20,10,2,'Chambre Rattanakosin','chambre','Chambre dans une maison traditionnelle thaie face aux temples du quartier historique.',2,385.00,7,'https://images.unsplash.com/photo-1590490360182-c33d57733427?w=800'),(21,11,2,'Maison de Ville Hoi An','maison','Maison de ville renovee avec jardin interieur au coeur de la vieille ville UNESCO.',4,560.00,7,'https://images.unsplash.com/photo-1570213489059-0aac6626cade?w=800'),(22,11,2,'Chambre An Bang','chambre','Chambre dans une villa a 5 min de la plage d\'An Bang, cadre bucolique et paisible.',2,315.00,7,'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=800'),(23,12,2,'Villa Sea Point','villa','Villa avec piscine surplombant l\'Atlantique, vue sur la Montagne de la Table.',6,1400.00,7,'https://images.unsplash.com/photo-1583608205776-bfd35f0d9f83?w=800'),(24,12,2,'Appartement Bo-Kaap','appartement','Appartement colore dans le quartier historique malais de Bo-Kaap, ambiance unique.',3,665.00,7,'https://images.unsplash.com/photo-1600585154526-990dced4db0d?w=800'),(25,13,2,'Appartement Palermo','appartement','Appartement design dans le quartier branche de Palermo, terrasse avec barbecue.',4,595.00,7,'https://images.unsplash.com/photo-1493809842364-78817add7ffb?w=800'),(26,13,2,'Loft San Telmo','autre','Loft industriel chic dans le quartier tango de San Telmo, pres de la feria.',2,490.00,7,'https://images.unsplash.com/photo-1536376072261-38c75010e6c9?w=800'),(27,14,2,'Casa Colonial Vedado','maison','Maison coloniale restauree dans le Vedado, patio ombrage et mobilier d\'epoque.',4,455.00,7,'https://images.unsplash.com/photo-1570213489059-0aac6626cade?w=800'),(28,14,2,'Chambre Habana Vieja','chambre','Chambre chez l\'habitant en Vieille Havane, immersion dans la culture cubaine.',2,280.00,7,'https://images.unsplash.com/photo-1595521624943-f35b4e4c7163?w=800'),(29,15,2,'Appartement Bondi Beach','appartement','Appartement a 200 m de Bondi Beach, terrasse avec vue sur l\'ocean Pacifique.',3,1050.00,7,'https://images.unsplash.com/photo-1523217582562-09d0def993a6?w=800'),(30,15,2,'Maison Surry Hills','maison','Maison tendance dans le quartier gastronomique de Surry Hills, proche du CBD.',3,770.00,7,'https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?w=800'),(31,16,2,'Villa Nungwi','villa','Villa les pieds dans l\'eau a Nungwi, eau turquoise et couchers de soleil magiques.',2,910.00,7,'https://images.unsplash.com/photo-1540541338287-41700207dee6?w=800'),(32,16,2,'Appartement Stone Town','appartement','Appartement dans une maison arabe du XVIIIe siecle en pleine medina Stone Town.',3,525.00,7,'https://images.unsplash.com/photo-1519999482648-25049ddd37b1?w=800'),(33,17,2,'Appartement Jordaan','appartement','Appartement traditionnel sur un canal dans le quartier Jordaan, vue peniches.',2,945.00,7,'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=800'),(34,17,2,'Studio De Pijp','autre','Studio moderne dans le quartier multiculturel De Pijp, marche Albert Cuyp proche.',2,665.00,7,'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=800'),(35,18,2,'Appartement Brooklyn','appartement','Appartement loft a Brooklyn, vue sur Manhattan, a 10 min du centre en metro.',4,1260.00,7,'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=800'),(36,18,2,'Studio Manhattan','autre','Studio compact en plein Midtown Manhattan, pres de Times Square et Central Park.',2,1400.00,7,'https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?w=800'),(37,19,2,'Appartement Nimman','appartement','Appartement contemporain dans le quartier tendance de Nimmanhaemin, cafes et galeries.',3,420.00,7,'https://images.unsplash.com/photo-1598928506311-c55ded91a20c?w=800'),(38,19,2,'Chambre Temple District','chambre','Chambre dans une guesthouse au coeur du quartier des temples bouddhistes.',2,245.00,7,'https://images.unsplash.com/photo-1590490360182-c33d57733427?w=800'),(39,20,2,'Appartement Dubai Marina','appartement','Appartement de luxe avec vue sur la marina, piscine sur le toit et acces plage JBR.',4,1540.00,7,'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=800'),(40,20,2,'Studio Downtown Dubai','autre','Studio elegant face au Burj Khalifa, fontaines dansantes visibles depuis le balcon.',2,1120.00,7,'https://images.unsplash.com/photo-1599982890963-3aabd60064d2?w=800'),(41,21,2,'Appartement Sultanahmet','appartement','Appartement avec vue sur la Mosquee Bleue et Sainte-Sophie, en plein coeur historique.',3,910.00,7,'https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?w=800'),(42,21,2,'Maison Balat','maison','Maison de caractere dans le pittoresque quartier de Balat, facades colorees et ruelles.',4,700.00,7,'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?w=800');
UNLOCK TABLES;
DROP TABLE IF EXISTS `notification`;
CREATE TABLE `notification` (
  `id_notification` int NOT NULL AUTO_INCREMENT,
  `id_utilisateur` int NOT NULL,
  `id_sejour` int DEFAULT NULL,
  `type` enum('reservation_confirmee','depart_proche','modification','activite_a_venir','systeme') NOT NULL,
