INSERT INTO `notification` VALUES (1,7,1,'reservation_confirmee','Séjour Bali confirmé !','Votre séjour à Ubud du 01/07 au 29/07 est confirmé. Réf. VV-2026-000001.',1,'2026-05-26 20:20:47'),(2,7,1,'depart_proche','Départ dans 5 jours','Votre vol Paris CDG → Bali décolle dans 5 jours. Vérifiez vos documents de voyage.',1,'2026-05-26 20:20:47'),(3,7,1,'activite_a_venir','Randonnée Batur demain','Votre ascension du volcan Batur démarre demain à 2h du matin. Lampe frontale et vêtements chauds indispensables.',1,'2026-05-26 20:20:47'),(4,7,7,'modification','Séjour Medellín annulé','Votre séjour Medellín a bien été annulé. Aucun prélèvement n\'a été effectué.',1,'2026-05-26 20:20:47'),(5,8,2,'reservation_confirmee','Lisbonne confirmé !','Votre séjour à Lisbonne du 01/08 au 21/08 est confirmé. Réf. VV-2026-000002.',1,'2026-05-26 20:20:47'),(6,8,2,'depart_proche','Départ dans une semaine','Votre vol Paris CDG → Lisbonne est dans 7 jours. Check-in en ligne disponible.',0,'2026-05-26 20:20:47'),(7,9,3,'reservation_confirmee','Kyoto confirmé !','Votre séjour à Kyoto du 01/09 au 28/09 est confirmé. Réf. VV-2026-000003.',0,'2026-05-26 20:20:47'),(8,9,3,'activite_a_venir','Cérémonie du thé le 06/09','Rappel : votre cérémonie du thé Urasenke le 6 septembre à 14h. Tenue sobre recommandée.',0,'2026-05-26 20:20:47'),(9,12,6,'reservation_confirmee','Oaxaca confirmé !','Votre séjour à Oaxaca du 15/06 au 13/07 est confirmé. Réf. VV-2026-000006.',1,'2026-05-26 20:20:47'),(10,12,6,'activite_a_venir','Atelier teinture le 20/06','Rappel : atelier de teinture zapotèque le 20 juin à 9h. Prévoyez des vêtements que vous ne craignez pas de tacher.',0,'2026-05-26 20:20:47'),(11,10,NULL,'systeme','Bienvenue sur VoyageVista !','Commencez à composer votre premier séjour slow travel. Consultez nos destinations et construisez votre itinéraire.',0,'2026-05-26 20:20:47'),(12,11,NULL,'systeme','Bienvenue sur VoyageVista !','Commencez à composer votre premier séjour slow travel. Consultez nos destinations et construisez votre itinéraire.',0,'2026-05-26 20:20:47'),(13,2,1,'reservation_confirmee','Nouvelle réservation','Lucas Bernard a réservé la Villa Ubud Serenity du 01/07 au 29/07/2026.',1,'2026-05-26 20:20:47'),(14,3,2,'reservation_confirmee','Nouvelle réservation','Emma Dubois a réservé la Maison Alfama dos Azulejos du 01/08 au 21/08/2026.',0,'2026-05-26 20:20:47'),(15,4,3,'reservation_confirmee','Nouvelle réservation','Thomas Petit a réservé la Machiya Higashiyama du 01/09 au 28/09/2026.',0,'2026-05-26 20:20:47'),(16,3,6,'reservation_confirmee','Nouvelle réservation','Léa Fontaine a réservé la Casa Colonial Oaxaca Centro du 15/06 au 13/07/2026.',0,'2026-05-26 20:20:47'),(17,7,9,'reservation_confirmee','Réservation confirmée !','Votre séjour \"Mon séjour\" a été confirmé. Référence : VV-2026-00009',1,'2026-05-26 20:36:31');
